-- Avstemming mot ekte Entelios-eksport (målepunktsliste-22092026.xlsx,
-- lastet ned fra "Min side" hos Entelios) - 63 unike MålepunktID-er som
-- Entelios selv bekrefter er registrert under Adaptic Technology AS
-- (org.nr 927167778). Fasit-listen under er hentet direkte fra fila.
--
-- Mål: "Registrert Entelios" + "Cloud-oppsett" + "I drift" til sammen skal
-- 100% matche disse 63 - verken færre (noe reelt registrert som henger
-- igjen på et tidligere steg) eller flere (noe markert registrert/aktivt
-- som IKKE faktisk står hos Entelios - se Elgsetergate 16, sept. 2026).

-- ============================================================
-- STEG 1: Rader som ER bekreftet av Entelios, men som i Strømflyt
-- fortsatt henger på et steg FØR "Bekreftet" - dette er "hullene" som
-- gjør at totalen ikke stemmer. Kjør SELECT-en først for å se dem.
-- ============================================================

select id, kunde, bygg, maalepunkt_id, status
from public.strombestillinger
where maalepunkt_id in (
  '707057500012420699', '707057500015230677', '707057500015924668', '707057500016349149',
  '707057500016456687', '707057500016469472', '707057500016470478', '707057500017421691',
  '707057500017436626', '707057500027020082', '707057500027020167', '707057500027020181',
  '707057500027020204', '707057500027020211', '707057500027020228', '707057500027020235',
  '707057500027023649', '707057500027023670', '707057500027475851', '707057500027475868',
  '707057500027529103', '707057500027595993', '707057500027752334', '707057500027988481',
  '707057500027988498', '707057500027988528', '707057500027988535', '707057500027988542',
  '707057500027988559', '707057500028111130', '707057500028120675', '707057500028318492',
  '707057500028321928', '707057500028710135', '707057500028710142', '707057500028710210',
  '707057500028754207', '707057500029065883', '707057500029181446', '707057500029215004',
  '707057500029305897', '707057500029361244', '707057500029361251', '707057500029361268',
  '707057500029395058', '707057500029446392', '707057500029639299', '707057500029721116',
  '707057500029735779', '707057500029737308', '707057500029799986', '707057500029888925',
  '707057500029888932', '707057500030092977', '707057500034533933', '707057500049193191',
  '707057500052826215', '707057500056438209', '707057500056553025', '707057500056734257',
  '707057500057446821', '707057500057601633', '707057500070054379'
)
and status not in ('Bekreftet', 'Satt opp i Cloud', 'Aktiv');

-- Bekreftet er ekte Entelios-data her - trygt å heve disse direkte, i
-- motsetning til Cloud-treff som bare er et signal. Kjør denne etterpå:
-- "Sjekk i Cloud" (knapp eller bulk) vil deretter kunne heve de som
-- faktisk HAR Cloud-data videre til Satt opp i Cloud/Aktiv, siden de nå
-- passerer Bekreftet-sperren fra i går.

update public.strombestillinger
set status = 'Bekreftet'
where maalepunkt_id in (
  '707057500012420699', '707057500015230677', '707057500015924668', '707057500016349149',
  '707057500016456687', '707057500016469472', '707057500016470478', '707057500017421691',
  '707057500017436626', '707057500027020082', '707057500027020167', '707057500027020181',
  '707057500027020204', '707057500027020211', '707057500027020228', '707057500027020235',
  '707057500027023649', '707057500027023670', '707057500027475851', '707057500027475868',
  '707057500027529103', '707057500027595993', '707057500027752334', '707057500027988481',
  '707057500027988498', '707057500027988528', '707057500027988535', '707057500027988542',
  '707057500027988559', '707057500028111130', '707057500028120675', '707057500028318492',
  '707057500028321928', '707057500028710135', '707057500028710142', '707057500028710210',
  '707057500028754207', '707057500029065883', '707057500029181446', '707057500029215004',
  '707057500029305897', '707057500029361244', '707057500029361251', '707057500029361268',
  '707057500029395058', '707057500029446392', '707057500029639299', '707057500029721116',
  '707057500029735779', '707057500029737308', '707057500029799986', '707057500029888925',
  '707057500029888932', '707057500030092977', '707057500034533933', '707057500049193191',
  '707057500052826215', '707057500056438209', '707057500056553025', '707057500056734257',
  '707057500057446821', '707057500057601633', '707057500070054379'
)
and status not in ('Bekreftet', 'Satt opp i Cloud', 'Aktiv');

-- ============================================================
-- STEG 2: Rader som Strømflyt markerer som Bekreftet/Satt opp i Cloud/Aktiv,
-- men som IKKE finnes i Entelios sin egen liste i det hele tatt - dette er
-- "falske positiver" (Elgsetergate 16-mønsteret: reell Cloud-data, men
-- ALDRI faktisk registrert av Adaptic hos Entelios). Se over hver av dem
-- MANUELT - ingen automatisk retting her, siden årsaken kan variere
-- (fakturamottaker-avtale, feilregistrering, e.l.).
-- ============================================================

select id, kunde, bygg, maalepunkt_id, status, kommentar
from public.strombestillinger
where status in ('Bekreftet', 'Satt opp i Cloud', 'Aktiv')
  and maalepunkt_id not in (
    '707057500012420699', '707057500015230677', '707057500015924668', '707057500016349149',
    '707057500016456687', '707057500016469472', '707057500016470478', '707057500017421691',
    '707057500017436626', '707057500027020082', '707057500027020167', '707057500027020181',
    '707057500027020204', '707057500027020211', '707057500027020228', '707057500027020235',
    '707057500027023649', '707057500027023670', '707057500027475851', '707057500027475868',
    '707057500027529103', '707057500027595993', '707057500027752334', '707057500027988481',
    '707057500027988498', '707057500027988528', '707057500027988535', '707057500027988542',
    '707057500027988559', '707057500028111130', '707057500028120675', '707057500028318492',
    '707057500028321928', '707057500028710135', '707057500028710142', '707057500028710210',
    '707057500028754207', '707057500029065883', '707057500029181446', '707057500029215004',
    '707057500029305897', '707057500029361244', '707057500029361251', '707057500029361268',
    '707057500029395058', '707057500029446392', '707057500029639299', '707057500029721116',
    '707057500029735779', '707057500029737308', '707057500029799986', '707057500029888925',
    '707057500029888932', '707057500030092977', '707057500034533933', '707057500049193191',
    '707057500052826215', '707057500056438209', '707057500056553025', '707057500056734257',
    '707057500057446821', '707057500057601633', '707057500070054379'
  );

-- ============================================================
-- STEG 3: De to Elgsetergate 16-målerne (Borg Forvaltning) - bekreftet
-- fraværende fra Entelios-eksporten (sjekket 2026-09-22). Ikke Adaptic sin
-- avtale å registrere (Borg har egen avtale, Adaptic er fakturamottaker),
-- men satt til "Innmeldt" på eksplisitt ønske - klare til innmelding den
-- dagen det eventuelt blir aktuelt, i stedet for å late som de er
-- registrert.
-- ============================================================

update public.strombestillinger
set status = 'Innmeldt'
where maalepunkt_id in ('707057500069389390', '707057500069389376');

-- ============================================================
-- STEG 4: Sanity-sjekk etterpå - tallet under skal bli 63 (evt. 61 hvis du
-- fortsatt holder de to Elgseter-radene utenfor, siden de nå er Innmeldt).
-- ============================================================

select count(*) as antall_bekreftet_satt_opp_eller_aktiv
from public.strombestillinger
where status in ('Bekreftet', 'Satt opp i Cloud', 'Aktiv');
